function normalize(raw, idx) {
 const get=(...keys)=>{for(const k of keys){if(raw[k]!==undefined&&raw[k]!==null&&raw[k]!=='')return raw[k]}return ''};
 const address=String(get('Address','URL','url')||`https://example.com/page-${idx+1}/`);
 const statusValue=get('Status Code','status_code','status');
 const parsedStatus=Number(statusValue);
 const status=Number.isFinite(parsedStatus)?parsedStatus:({success:200,'not found':404,'moved permanently':301,'moved temporarily':302}[String(statusValue).toLowerCase()]||0);
 const title=String(get('Title 1','title','Title')||'');
 const meta=String(get('Meta Description 1','meta_description','Meta description')||'');
 const h1=String(get('H1-1','h1','H1')||'');
 const canon=String(get('Canonical Link Element 1','canonical')||'');
 const word=Number(get('Word Count','word_count')||0);
 const depth=Number(get('Crawl Depth','depth')||0);
 const inlinks=Number(get('Unique Inlinks','Inlinks','inlinks')||0);
 const outlinks=Number(get('Unique Outlinks','Outlinks','outlinks')||0);
 const response=Number(get('Response Time','response_time')||0);
 const size=Number(get('Size (bytes)','size_bytes')||0);
 const robots=String(get('Meta Robots 1','meta_robots')||'');
 const xRobots=String(get('X-Robots-Tag 1','x_robots_tag')||'');
 const indexability=String(get('Indexability','indexability')||(status>=300?'Non-Indexable':'Unknown'));
 const contentType=String(get('Content Type')||'');
 const diag=(raw.__diagnostics&&typeof raw.__diagnostics==='object')?raw.__diagnostics:{};
 const asBool=(v)=>v===true||String(v).toLowerCase()==='true'||String(v)==='1';
 const htmlDetected=diag.html_detected!==undefined?asBool(diag.html_detected):/text\/html|application\/xhtml\+xml/i.test(contentType);
 const bodyTruncated=asBool(diag.body_truncated);
 const extractionStatus=String(diag.extraction_status||((status>=200&&status<300&&htmlDetected)?'checked':'not_applicable'));
 const renderedChecked=asBool(diag.rendered_checked);
 const canAuditMetadata=status>=200&&status<300&&htmlDetected&&extractionStatus==='checked'&&!bodyTruncated;
 const missingSeverity=renderedChecked?'Error':'Notice';
 const missingEvidence=(field)=>renderedChecked?`No ${field} found in rendered HTML.`:`No ${field} found in raw response HTML. JavaScript rendering was not checked, so verify before treating this as missing on the rendered page.`;
 const issues=[];
 if(status>=400)issues.push({name:status>=500?'Server error':'Broken page',category:'Links',severity:'Error',evidence:`HTTP ${status}`,fix:'Inspect the URL and restore the page or update links pointing to it.'});
 if(status>=300&&status<400)issues.push({name:'Redirecting URL',category:'Redirects',severity:'Notice',evidence:`HTTP ${status}`,fix:'Update internal links to point directly to the final destination.'});
 // Only run on-page checks on successful HTML responses whose extraction was complete.
 // A blocked URL, fetch failure, non-HTML response, or truncated body must not become a false missing-tag issue.
 if(canAuditMetadata){
  if(!title)issues.push({name:renderedChecked?'Missing title':'Title not found in raw HTML',category:'On-page',severity:missingSeverity,evidence:missingEvidence('title tag'),fix:renderedChecked?'Add a descriptive <title> element to the rendered document.':'Check the source HTML and enable JavaScript rendering before confirming this issue.'});
  if(title&&title.length>60)issues.push({name:'Title too long',category:'On-page',severity:'Warning',evidence:`${title.length} characters`,fix:'Consider shortening the title while retaining the primary topic.'});
  if(!meta){const og=asBool(diag.open_graph_description_present);issues.push({name:renderedChecked?'Missing meta description':'Meta description not found in raw HTML',category:'On-page',severity:missingSeverity,evidence:og?'An Open Graph description exists, but a standard meta name="description" was not found.':missingEvidence('meta description'),fix:renderedChecked?'Add a standard <meta name="description" content="..."> element if appropriate.':'Check raw source and enable JavaScript rendering before confirming this issue.'});}
  if(!h1)issues.push({name:renderedChecked?'Missing H1':'H1 not found in raw HTML',category:'Content',severity:missingSeverity,evidence:missingEvidence('H1 heading'),fix:renderedChecked?'Add a clear primary H1 heading where appropriate.':'Check raw source and enable JavaScript rendering before confirming this issue.'});
  if(word>0&&word<200)issues.push({name:'Thin content',category:'Content',severity:'Notice',evidence:`${word} words`,fix:'Review whether the page fully satisfies search intent; add useful content where needed.'});
 }
 if(/(?:^|[,\s])noindex(?:$|[,\s])/i.test(`${robots} ${xRobots}`))issues.push({name:'Noindex directive',category:'Indexability',severity:'Warning',evidence:`${robots} ${xRobots}`.trim(),fix:'Confirm that excluding this URL from search results is intentional.'});
 if(canon&&canon!==address)issues.push({name:'Canonical points elsewhere',category:'Indexability',severity:'Notice',evidence:canon,fix:'Verify that the canonical target is the preferred indexable URL.'});
 if(response>1000)issues.push({name:'Slow response',category:'Performance',severity:'Warning',evidence:`${response} ms`,fix:'Investigate server response time, caching, database calls and upstream services.'});
 return {id:idx+1,url:address,status,indexability,title,titleLength:Number(get('Title 1 Length')||title.length),meta,metaLength:Number(get('Meta Description 1 Length')||meta.length),h1,wordCount:word,canonical:canon,depth,inlinks,outlinks,response,size,robots,xRobots,contentType,language:String(get('Language')||''),redirectUrl:String(get('Redirect URL')||''),redirectType:String(get('Redirect Type')||''),timestamp:String(get('Crawl Timestamp')||''),extractionStatus,extractionNote:String(diag.note||''),renderedChecked,htmlDetected,bodyTruncated,diagnostics:diag,issues,raw};
}
